public class Mixed {
    public int classify(int a, int b, int c, int d, int e, int f, int g) {
        int result = 0;
        if (a > 0 && b > 0 && c > 0 && d > 0 && e > 0) {
            result += 1;
        }
        if (a > 1) { result += 2; } else if (b > 1) { result += 3; } else if (c > 1) { result += 4; }
        if (d > 1) { result += 5; } else if (e > 1) { result += 6; } else if (f > 1) { result += 7; }
